// Datapath: input registers, functional units, muxes and registers.
// Generated by the EC551 HLS tool from pdf_example.txt (asap schedule,
// 3 steps). Do not edit: rerun the tool instead.
module hls_datapath (
    input  wire clk,
    input  wire rst,
    input  wire en,
    input  wire in_we,
    input  wire [5:0] in_sel,
    input  wire [15:0] in_data,
    input  wire add0_b_sel,
    input  wire r0_we,
    input  wire r1_we,
    input  wire r2_we,
    input  wire r3_we,
    input  wire [1:0] view,
    input  wire [5:0] dbg_sel,
    output reg  [15:0] dbg_value
);

    // Input registers, loaded one at a time from the switches.
    reg [15:0] in_A, in_B;
    always @(posedge clk) begin
        if (rst) begin
            in_A <= 16'd0;
            in_B <= 16'd0;
        end else if (in_we) begin
            case (in_sel)
                6'd0: in_A <= in_data;
                6'd1: in_B <= in_data;
                default: ;
            endcase
        end
    end

    // Working registers. Values with non-overlapping lifetimes share one.
    reg [15:0] r0;  // X_1
    reg [15:0] r1;  // Y_1
    reg [15:0] r2;  // Z_1
    reg [15:0] r3;  // Q_1

    // Functional units and their input muxes.
    // add0: step 1 X_1 = A_0 + B_0; step 2 Y_1 = X_1 + A_0
    wire [15:0] add0_a = in_A;
    reg  [15:0] add0_b;
    always @* begin
        case (add0_b_sel)
            1'd0: add0_b = in_B;
            1'd1: add0_b = r0;
            default: add0_b = {16{1'b0}};
        endcase
    end
    wire [15:0] add0_y;
    adder #(.WIDTH(16)) u_add0 (.a(add0_a), .b(add0_b), .y(add0_y));

    // sub0: step 2 Z_1 = X_1 - B_0
    wire [15:0] sub0_a = r0;
    wire [15:0] sub0_b = in_B;
    wire [15:0] sub0_y;
    subtractor #(.WIDTH(16)) u_sub0 (.a(sub0_a), .b(sub0_b), .y(sub0_y));

    // mul0: step 3 Q_1 = B_0 * Z_1
    wire [15:0] mul0_a = in_B;
    wire [15:0] mul0_b = r2;
    wire [15:0] mul0_y;
    multiplier #(.WIDTH(16)) u_mul0 (.a(mul0_a), .b(mul0_b), .y(mul0_y));

    // Register input muxes.
    wire [15:0] r0_d = add0_y;
    wire [15:0] r1_d = add0_y;
    wire [15:0] r2_d = sub0_y;
    wire [15:0] r3_d = mul0_y;

    // A register only changes on an enabled edge with its write-enable set.
    always @(posedge clk) begin
        if (rst) begin
            r0 <= 16'd0;
            r1 <= 16'd0;
            r2 <= 16'd0;
            r3 <= 16'd0;
        end else if (en) begin
            if (r0_we) r0 <= r0_d;
            if (r1_we) r1 <= r1_d;
            if (r2_we) r2 <= r2_d;
            if (r3_we) r3 <= r3_d;
        end
    end

    // Observability: view picks the category, dbg_sel the item.
    always @* begin
        dbg_value = 16'd0;
        case (view)
            2'd0: begin  // functional unit outputs
                case (dbg_sel)
                    6'd0: dbg_value = add0_y;  // add0 (adder 0)
                    6'd1: dbg_value = sub0_y;  // sub0 (subtractor 0)
                    6'd2: dbg_value = mul0_y;  // mul0 (multiplier 0)
                    default: ;
                endcase
            end
            2'd1: begin  // outputs
                case (dbg_sel)
                    6'd0: dbg_value = r0;  // X (X_1)
                    6'd1: dbg_value = r1;  // Y (Y_1)
                    6'd2: dbg_value = r2;  // Z (Z_1)
                    6'd3: dbg_value = r3;  // Q (Q_1)
                    default: ;
                endcase
            end
            2'd2: begin  // registers
                case (dbg_sel)
                    6'd0: dbg_value = r0;  // X_1
                    6'd1: dbg_value = r1;  // Y_1
                    6'd2: dbg_value = r2;  // Z_1
                    6'd3: dbg_value = r3;  // Q_1
                    default: ;
                endcase
            end
            2'd3: begin  // inputs
                case (dbg_sel)
                    6'd0: dbg_value = in_A;  // A
                    6'd1: dbg_value = in_B;  // B
                    default: ;
                endcase
            end
        endcase
    end
endmodule
